function logZ(B, x, y, z, len, r, col) {
  const c = hex(col), cen = [x, y, z], seg = 6;
  for (let k = 0; k < seg; k++) {
    const a = k / seg * 6.283, b = (k + 1) / seg * 6.283, P = (zz, ang) => [x + Math.cos(ang) * r, y + Math.sin(ang) * r, zz];
    B.quad(P(z - len / 2, a), P(z - len / 2, b), P(z + len / 2, b), P(z + len / 2, a), c, cen);
    B.tri([x, y, z - len / 2], P(z - len / 2, b), P(z - len / 2, a), hex('#d9b38c'), cen); B.tri([x, y, z + len / 2], P(z + len / 2, a), P(z + len / 2, b), hex('#d9b38c'), cen);
  }
}
