  B.box(0, 0.3, -1.1, 0.88, 0.45, 0.6, hull); B.box(0, 0.75, -1.1, 0.92, 0.04, 0.64, trim);
  for (const s of [-1, 1]) for (const x of [-0.85, -1.25]) B.box(s * 0.455, 0.42, x + 0.1, 0.01, 0.12, 0.14, '#ffd27a');
  B.box(0, 0.3, 0.2, 0.84, 0.03, 2.1, '#9c6b45');
  const guns = level === 4 ? 4 : 2;
  for (let k = 0; k < guns; k++) for (const s of [-1, 1]) { const z = -0.55 + k * (level === 4 ? 0.42 : 0.7); B.box(s * 0.452, 0.0, z, 0.01, 0.12, 0.12, '#1c1a18'); B.beam([s * 0.4, 0.06, z], [s * 0.56, 0.06, z], 0.07, 0.07, '#2f2f33'); }
