    for (let r = 0; r < 2; r++) { const y = 0.8 + r * (h * 0.4), w = 1.3 - r * 0.35; B.box(0, y + h * 0.33, z, w, 0.025, 0.025, '#4a2e1e'); B.box(0, y, z + 0.03, w * 0.92, h * 0.32, 0.02, level === 4 && r === 0 ? '#f2ece2' : '#efe6d2'); }
    B.box(0.12, 0.3 + h - 0.12, z, 0.24, 0.12, 0.01, k === 0 ? '#c0504d' : '#3d6b8c');
