  for (let k = 0; k < 4; k++) for (const s of [-1, 1]) B.beam([s * 0.3, 0.12, -0.6 + k * 0.4], [s * 0.75, -0.2, -0.75 + k * 0.4], 0.025, 0.025, '#8b5a3c');
