        rect(0, 0, 1, 1, hex('#a39d93'), -0.004);
        const wet = (di, dj) => { const x = i + di, y = j + dj; if (!Sim.inB(x, y)) return true; const k = y * N + x; return S.road[k] !== 4 && !S.occ[k] && Sim.cellH(S, x, y) < QY - 0.05; };
        const ks = 0.09;
