        if (wet(0, -1)) rect(0, 0, 1, ks, KERB, 0.02); if (wet(0, 1)) rect(0, 1 - ks, 1, 1, KERB, 0.02);
        const sides = [[-1, 0], [1, 0], [0, -1], [0, 1]].filter(([di, dj]) => wet(di, dj));
