    let best = -1, bd = 1e9;
    for (let dj = -6; dj <= 6; dj++) for (let di = -6; di <= 6; di++) {
      const x = i + di, y = j + dj; if (!Sim.inB(x, y) || !this.waterGrid[y * N + x]) continue;
      if (min && Sim.cellH(this.S, x, y) > -min) continue;
      const d = Math.hypot(di, dj); if (d < bd) { bd = d; best = y * N + x; }
    }
