      const a = this.newAgent(hall, ...Sim.center(hall), 9 + k + b.id);
      a.temp = 'builder'; a.site = b.id; a.kid = false; a.hat = HATS[0 + (k % 2) * 2]; a.name = a.name.split(' ')[0] + ' the builder';
      const [cx, cz] = Sim.center(b), s = TYPES[b.type].size / 2 + 0.25, side = (k + b.id) % 4;
      const pt = [[cx - s, cz], [cx + s, cz], [cx, cz - s], [cx, cz + s]][side];
